/* ------------------------------------------------------------------ */
const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400&family=Jost:wght@300;400;500;600&display=swap');

.root{
  --gold:#C67F4D; --gold-soft:#E3A877; --gold-deep:#9E612F;
  --onyx:#0A0A0B; --carbon:#121110; --carbon-2:#1A1714;
  --ivory:#F1EBE3; --muted:#9A9082; --line:rgba(198,127,77,.26);
  background:var(--onyx); color:var(--ivory);
  font-family:'Jost',system-ui,sans-serif; font-weight:300;
  -webkit-font-smoothing:antialiased; overflow-x:hidden;
}
.root *{box-sizing:border-box; margin:0; padding:0;}
.root a{color:inherit; text-decoration:none;}
html{scroll-behavior:smooth; scroll-padding-top:84px;}
.root img{display:block;}

.eyebrow{font-size:.72rem; letter-spacing:.32em; text-transform:uppercase; color:var(--gold); font-weight:500; margin-bottom:1.1rem;}
.section-title{font-family:'Cormorant Garamond',serif; font-weight:500; font-size:clamp(2rem,5vw,3.4rem); line-height:1.06; letter-spacing:-.01em; color:var(--ivory);}
.section-title.center{text-align:center;}
.lead{font-size:1.18rem; line-height:1.6; color:var(--ivory); margin:1.4rem 0 1rem; font-weight:300;}
.body{font-size:1rem; line-height:1.75; color:var(--muted); font-weight:300;}
.gold-text{background:linear-gradient(100deg,var(--gold-deep),var(--gold-soft),var(--gold)); -webkit-background-clip:text; background-clip:text; color:transparent; font-style:italic;}
.link-gold{display:inline-block; margin-top:1.3rem; color:var(--gold); font-size:.82rem; letter-spacing:.16em; text-transform:uppercase; font-weight:500; transition:opacity .25s, transform .25s;}
.link-gold:hover{opacity:.7; transform:translateX(3px);}

.btn{display:inline-flex; align-items:center; justify-content:center; padding:.95rem 1.9rem; font-size:.78rem; letter-spacing:.2em; text-transform:uppercase; font-weight:500; cursor:pointer; border:none; position:relative; overflow:hidden; transition:transform .3s, box-shadow .3s;}
.btn-gold{background:linear-gradient(120deg,var(--gold-deep),var(--gold-soft) 48%,var(--gold-deep)); background-size:200% 100%; color:#241606;}
.btn-gold::after{content:""; position:absolute; inset:0; background:linear-gradient(110deg,transparent 30%,rgba(255,255,255,.5) 50%,transparent 70%); transform:translateX(-120%); transition:transform .7s ease;}
.btn-gold:hover{transform:translateY(-2px); box-shadow:0 12px 30px -10px rgba(198,127,77,.55);}
.btn-gold:hover::after{transform:translateX(120%);}
.btn-ghost{background:transparent; color:var(--ivory); border:1px solid var(--line);}
.btn-ghost:hover{border-color:var(--gold); color:var(--gold); transform:translateY(-2px);}
.btn-block{width:100%;}

.nav{position:fixed; top:0; left:0; right:0; z-index:50; transition:background .4s, border-color .4s; border-bottom:1px solid transparent;}
.nav-solid{background:rgba(10,10,11,.85); backdrop-filter:blur(14px); border-color:var(--line);}
.nav-inner{max-width:1200px; margin:0 auto; padding:1.1rem 1.5rem; display:flex; align-items:center; justify-content:space-between; gap:1rem;}
.wordmark{display:flex; align-items:center;}
.nav-logo{height:46px; width:auto; object-fit:contain;}
.nav-links{display:flex; gap:2.2rem;}
.nav-links a{font-size:.82rem; letter-spacing:.14em; text-transform:uppercase; opacity:.85; transition:color .25s,opacity .25s;}
.nav-links a:hover{color:var(--gold); opacity:1;}
.nav-cta{padding:.7rem 1.5rem;}
.nav-burger{display:none; background:none; border:none; color:var(--gold); cursor:pointer;}
.nav-mobile{display:none; flex-direction:column; background:rgba(10,10,11,.97); border-top:1px solid var(--line); padding:1rem 1.5rem;}
.nav-mobile a{padding:.85rem 0; font-size:.85rem; letter-spacing:.16em; text-transform:uppercase; border-bottom:1px solid rgba(255,255,255,.05);}

.hero{position:relative; min-height:100vh; display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center; padding:7rem 1.5rem 4rem; overflow:hidden;}
.hero-video{position:absolute; inset:0; width:100%; height:100%; object-fit:cover; z-index:0; animation:slowzoom 22s ease-in-out infinite alternate;}
@keyframes slowzoom{from{transform:scale(1);}to{transform:scale(1.09);}}
.hero-scrim{position:absolute; inset:0; z-index:1; background:linear-gradient(180deg,rgba(8,8,9,.74) 0%,rgba(8,8,9,.55) 40%,rgba(8,8,9,.82) 100%);}
.hero-content{position:relative; z-index:2; max-width:860px;}
.hero-logo{width:auto; height:auto; max-width:188px; margin:0 auto 1.7rem; object-fit:contain;}
.hero-title{font-family:'Cormorant Garamond',serif; font-weight:500; font-size:clamp(2.4rem,6.4vw,5rem); line-height:1.04; letter-spacing:-.015em; color:var(--ivory);}
.hero-sub{max-width:540px; margin:1.6rem auto 2.4rem; font-size:1.1rem; line-height:1.65; color:rgba(241,235,227,.78); font-weight:300;}
.hero-cta{display:flex; gap:1rem; justify-content:center; flex-wrap:wrap;}
.scroll-cue{position:absolute; bottom:2rem; z-index:2; color:var(--gold); opacity:.8; animation:bob 2.4s ease-in-out infinite;}
@keyframes bob{0%,100%{transform:translateY(0);}50%{transform:translateY(7px);}}
.hero-fade{opacity:0; transform:translateY(22px); animation:fadeUp .9s cubic-bezier(.2,.7,.2,1) forwards;}
@keyframes fadeUp{to{opacity:1; transform:none;}}

.section{max-width:1200px; margin:0 auto; padding:6.5rem 1.5rem;}
.section-dark{max-width:none; background:var(--carbon);}
.section-dark > *{max-width:1200px; margin-left:auto; margin-right:auto;}
.section-head{text-align:center; max-width:620px; margin:0 auto 3.5rem;}
.section-head .eyebrow{text-align:center;}
.section-intro{margin-top:1.1rem; color:var(--muted); line-height:1.6;}
.grid-2{display:grid; grid-template-columns:1fr 1fr; gap:4rem; align-items:center;}

.ornament{display:flex; align-items:center; justify-content:center; gap:1rem; padding:1rem 1.5rem; max-width:1200px; margin:0 auto;}
.orn-line{height:1px; width:90px; background:linear-gradient(90deg,transparent,var(--gold));}
.ornament .orn-line:last-child{background:linear-gradient(90deg,var(--gold),transparent);}
.orn-diamond{width:7px; height:7px; background:var(--gold); transform:rotate(45deg);}

.photo{position:relative; overflow:hidden; background:var(--carbon-2); border:1px solid var(--line);}
.photo img{width:100%; height:100%; object-fit:cover; transition:transform .8s ease;}
.photo:hover img{transform:scale(1.05);}
.about-photo{aspect-ratio:4/5; border-radius:2px;}

.suites{display:grid; grid-template-columns:repeat(3,1fr); gap:2rem;}
.suite-card{background:var(--carbon); border:1px solid var(--line); border-radius:2px; overflow:hidden; transition:transform .4s, border-color .4s, box-shadow .4s; height:100%;}
.suite-card:hover{transform:translateY(-6px); border-color:rgba(198,127,77,.55); box-shadow:0 24px 50px -28px rgba(0,0,0,.9);}
.suite-photo{aspect-ratio:3/2;}
.suite-body{padding:1.8rem;}
.suite-name{font-family:'Cormorant Garamond',serif; font-weight:600; font-size:1.65rem; margin-bottom:.6rem;}
.suite-foot{display:flex; align-items:flex-end; justify-content:space-between; margin-top:1.5rem; padding-top:1.2rem; border-top:1px solid rgba(255,255,255,.06);}
.suite-price{font-family:'Cormorant Garamond',serif; font-size:1.55rem; color:var(--gold); line-height:1;}
.suite-price em{display:block; font-family:'Jost',sans-serif; font-style:normal; font-size:.6rem; letter-spacing:.22em; text-transform:uppercase; color:var(--muted); margin-bottom:.3rem;}
.suite-per{font-size:.75rem; color:var(--muted);}
.suite-foot .link-gold{margin-top:0;}

.exp-grid{display:grid; grid-template-columns:repeat(3,1fr); gap:1.5rem;}
.exp-card{padding:2.2rem 1.8rem; border:1px solid rgba(255,255,255,.06); border-radius:2px; transition:border-color .35s, background .35s; height:100%;}
.exp-card:hover{border-color:var(--line); background:rgba(198,127,77,.05);}
.exp-icon{color:var(--gold); margin-bottom:1.2rem;}
.exp-title{font-family:'Cormorant Garamond',serif; font-weight:600; font-size:1.45rem; margin-bottom:.5rem;}
.exp-text{font-size:.95rem; line-height:1.65; color:var(--muted);}

.gallery{display:grid; grid-template-columns:repeat(4,1fr); grid-auto-rows:175px; gap:1rem;}
.gallery .g{border-radius:2px;}
.g-cap{position:absolute; bottom:0; left:0; right:0; padding:1.4rem .9rem .8rem; font-size:.66rem; letter-spacing:.2em; text-transform:uppercase; color:var(--ivory); background:linear-gradient(0deg,rgba(8,8,9,.8),transparent); opacity:0; transition:opacity .35s; z-index:2;}
.g:hover .g-cap{opacity:1;}
.g1{grid-column:span 2; grid-row:span 2;}
.g2{grid-column:span 2; grid-row:span 1;}
.g3{grid-column:span 1; grid-row:span 1;}
.g4{grid-column:span 1; grid-row:span 1;}
.g5{grid-column:span 2; grid-row:span 1;}

.quote-section{text-align:center;}
.quote-wrap{max-width:760px; margin:0 auto; position:relative;}
.quote-mark{font-family:'Cormorant Garamond',serif; font-size:6rem; line-height:0; color:var(--gold); opacity:.4; display:block; height:2.2rem;}
.quote{font-family:'Cormorant Garamond',serif; font-weight:400; font-style:italic; font-size:clamp(1.5rem,3.4vw,2.3rem); line-height:1.4; color:var(--ivory);}
.quote-author{margin-top:1.8rem; font-size:.78rem; letter-spacing:.22em; text-transform:uppercase; color:var(--gold);}

.reserve-grid{align-items:start;}
.contact-list{list-style:none; margin-top:2rem; display:flex; flex-direction:column; gap:1rem;}
.contact-list li{display:flex; align-items:center; gap:.8rem; color:var(--muted); font-size:.95rem;}
.ci{color:var(--gold); flex-shrink:0;}
.booking{background:var(--onyx); border:1px solid var(--line); border-radius:2px; padding:2rem;}
.field{margin-bottom:1.2rem;}
.field label{display:block; font-size:.68rem; letter-spacing:.2em; text-transform:uppercase; color:var(--muted); margin-bottom:.5rem;}
.field input,.field select{width:100%; background:var(--carbon-2); border:1px solid rgba(255,255,255,.08); color:var(--ivory); padding:.85rem 1rem; font-family:'Jost',sans-serif; font-size:.95rem; border-radius:2px; outline:none; transition:border-color .25s;}
.field input:focus,.field select:focus{border-color:var(--gold);}
.field input::-webkit-calendar-picker-indicator{filter:invert(.7) sepia(1) saturate(3) hue-rotate(-5deg);}
.booking-msg{margin-top:1rem; font-size:.88rem; line-height:1.5; padding:.85rem 1rem; border-radius:2px;}
.msg-ok{color:var(--gold-soft); background:rgba(198,127,77,.12); border:1px solid var(--line);}
.msg-warn{color:#e8c9a0; background:rgba(255,180,120,.08); border:1px solid rgba(255,180,120,.2);}

.footer{background:var(--carbon); border-top:1px solid var(--line); padding:4.5rem 1.5rem 2rem;}
.footer-inner{max-width:1200px; margin:0 auto; display:grid; grid-template-columns:2fr 1fr 1fr; gap:3rem;}
.footer-logo{width:auto; height:54px; object-fit:contain; margin-bottom:1.2rem;}
.footer-brand .footer-blurb{max-width:340px; color:var(--muted); font-size:.92rem; line-height:1.7;}
.footer-col h4{font-size:.72rem; letter-spacing:.22em; text-transform:uppercase; color:var(--gold); margin-bottom:1.2rem; font-weight:500;}
.footer-col a{display:block; color:var(--muted); font-size:.9rem; padding:.4rem 0; transition:color .25s;}
.footer-col a:hover{color:var(--ivory);}
.footer-bottom{max-width:1200px; margin:3.5rem auto 0; padding-top:1.8rem; border-top:1px solid rgba(255,255,255,.06); display:flex; justify-content:space-between; flex-wrap:wrap; gap:.5rem; font-size:.78rem; color:var(--muted);}
.footer-credit{color:var(--gold); opacity:.75;}

.reveal{opacity:0; transform:translateY(28px); transition:opacity .9s cubic-bezier(.2,.7,.2,1), transform .9s cubic-bezier(.2,.7,.2,1);}
.reveal-in{opacity:1; transform:none;}

@media(max-width:860px){
  .nav-links,.nav-cta{display:none;}
  .nav-burger{display:block;}
  .nav-mobile{display:flex;}
  .grid-2{grid-template-columns:1fr; gap:2.5rem;}
  .suites{grid-template-columns:1fr;}
  .exp-grid{grid-template-columns:1fr 1fr;}
  .gallery{grid-template-columns:1fr 1fr; grid-auto-rows:150px;}
  .g1,.g2,.g5{grid-column:span 2;}
  .g1{grid-row:span 1;}
  .footer-inner{grid-template-columns:1fr;}
  .section{padding:4.5rem 1.5rem;}
}
@media(max-width:520px){
  .exp-grid{grid-template-columns:1fr;}
  .gallery{grid-template-columns:1fr;}
  .g1,.g2,.g5{grid-column:span 1;}
}
@media(prefers-reduced-motion:reduce){
  html{scroll-behavior:auto;}
  .reveal,.hero-fade,.scroll-cue,.hero-video,.photo img,.btn,.suite-card{animation:none!important; transition:none!important; opacity:1!important; transform:none!important;}
}
`;
